B.aHA=s(["- \u0644\u064e\u0627 \u062d\u064e\u0648\u0644\u064e \u0648\u064e\u0644\u064e\u0627 \u0642\u0648\u0629\u064e \u0625\u0650\u0644\u0627 \u0628\u0627\u0644\u0644\u0651\u064e\u0647.","- \u0644\u064e\u0627 \u0625\u0644\u064e\u0647 \u0625\u0644\u064e\u0651\u0627 \u0623\u0646\u062a\u064e \u0633\u064f\u0628\u062d\u064e\u0627\u0646\u0643\u064e \u0625\u0650\u0646\u0650\u0651\u064a \u0643\u064f\u0646\u062a \u0645\u0650\u0646 \u0627\u0644\u0638\u0627\u0644\u0650\u0645\u064a\u0646.","- \u0627\u0644\u0644\u0647\u064f\u0645\u0651\u064e \u0625\u0646\u064a \u0639\u0628\u062f\u064f\u0643 \u0627\u0628\u0646 \u0639\u0628\u062f\u0650\u0643 \u0627\u0628\u0646\u064f \u0623\u0645\u062a\u0650\u0643 \u0646\u0627\u0635\u064a\u062a\u064a \u0628\u064a\u062f\u0650\u0643 \u0645\u0627\u0636\u064d \u0641\u064a\u0651\u064e \u062d\u064f\u0643\u0645\u0643 \u0639\u064e\u062f\u0644 \u0641\u064a\u0651\u064e \u0642\u0636\u0627\u0624\u0643 \u0623\u0633\u0623\u0644\u0643 \u0628\u0643\u0644 \u0627\u0633\u0645\u064d \u0647\u0648 \u0644\u0643 \u0633\u0645\u064a\u062a \u0628\u0647 \u0646\u0641\u0633\u0643 \u0623\u0648 \u0639\u0644\u0645\u062a\u0647 \u0623\u062d\u062f\u064b\u0627 \u0645\u0650\u0646 \u062e\u0644\u0642\u0650\u0643 \u0623\u0648 \u0623\u0646\u0632\u0644\u062a\u0647 \u0641\u064a \u0643\u062a\u0627\u0628\u0643 \u0623\u0648 \u0627\u0633\u062a\u0623\u062b\u0631\u062a \u0628\u0647 \u0641\u064a \u0639\u0644\u0645\u0650 \u0627\u0644\u063a\u064a\u0628 \u0639\u0646\u062f\u064e\u0643 \u0623\u0646 \u062a\u062c\u0639\u0644\u064e \u0627\u0644\u0642\u0631\u0622\u0646 \u0631\u0628\u064a\u0639 \u0642\u0644\u0628\u064a \u0648\u0646\u0648\u0631\u064e \u0635\u062f\u0631\u064a \u0648\u062c\u0644\u0627\u0621\u064e \u062d\u064f\u0632\u0646\u064a \u0648\u0630\u0647\u0627\u0628\u064e \u0647\u0645\u0651\u064a.","- \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0627\u0644\u0639\u0638\u064a\u0645 \u0627\u0644\u062d\u0644\u064a\u0645 \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0631\u0628 \u0627\u0644\u0633\u0645\u0648\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0636 \u0648\u0631\u0628 \u0627\u0644\u0639\u0631\u0634 \u0627\u0644\u0639\u0638\u064a\u0645.","- \u0627\u0644\u0644\u0647\u064f\u0645\u0651\u064e \u0625\u0646\u064a \u0623\u0639\u064f\u0648\u0630 \u0628\u0643 \u0645\u0650\u0646 \u0627\u0644\u0647\u0645 \u0648\u0627\u0644\u062d\u0632\u0646\u0650\u060c \u0648\u0623\u0639\u064f\u0648\u0630 \u0628\u0643 \u0645\u0646 \u0627\u0644\u0639\u064e\u062c\u0632\u0650 \u0648\u0627\u0644\u0643\u064e\u0633\u064e\u0644\u0650\u060c \u0648\u0623\u0639\u064f\u0648\u0630 \u0628\u0643 \u0645\u0646 \u0627\u0644\u062c\u064f\u0628\u0646 \u0648\u0627\u0644\u0628\u064f\u062e\u0644\u060c \u0648\u0623\u0639\u064f\u0648\u0630 \u0628\u0650\u0643\u064e \u0645\u0650\u0646 \u063a\u0644\u0628\u064e\u0629\u0650 \u0627\u0644\u062f\u064a\u0646\u0650 \u0648\u0642\u0647\u0631 \u0627\u0644\u0631\u062c\u0627\u0644\u0650.","- \u0627\u0644\u0644\u0647\u064f\u0645\u0651\u064e \u0625\u0644\u064a\u0643 \u0623\u0634\u0643\u0648 \u0636\u0639\u0641 \u0642\u0648\u062a\u064a \u0648\u0642\u0644\u0629 \u062d\u064a\u0644\u062a\u064a \u0648\u0647\u0648\u0627\u0646\u064a \u0639\u0644\u0649 \u0627\u0644\u0646\u0627\u0633\u060c \u0623\u0646\u062a \u0623\u0631\u062d\u0645 \u0627\u0644\u0631\u0627\u062d\u0645\u064a\u0646 \u0648\u0623\u0646\u062a \u0631\u0628\u0649 \u0625\u0644\u0649 \u0645\u0646 \u062a\u0643\u0644\u0646\u064a\u060c \u0625\u0644\u0649 \u0639\u062f\u0648 \u064a\u062a\u062c\u0647\u0645\u0646\u064a \u0623\u0648 \u0625\u0644\u0649 \u0642\u0631\u064a\u0628 \u0645\u0644\u0643\u062a\u0647 \u0623\u0645\u0631\u064a\u060c \u0625\u0646 \u0644\u0645 \u064a\u0643\u0646 \u0628\u0643 \u0639\u0644\u064a \u063a\u0636\u0628\u064c \u0641\u0644\u0627 \u0623\u0628\u0627\u0644\u064a\u060c \u0623\u0639\u0648\u0630 \u0628\u0646\u0648\u0631 \u0648\u062c\u0647\u0643 \u0627\u0644\u0630\u064a \u0623\u0634\u0631\u0642\u062a \u0644\u0647 \u0627\u0644\u0638\u0644\u0645\u0627\u062a \u0648\u0635\u0644\u062d \u0639\u0644\u064a\u0647 \u0623\u0645\u0631 \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0627\u0644\u0622\u062e\u0631\u0629\u060c \u0623\u0646 \u062a\u0646\u0632\u0644 \u0639\u0644\u064a \u063a\u0636\u0628\u0643 \u0623\u0648 \u0633\u062e\u0637\u0643\u060c \u0644\u0643 \u0627\u0644\u0639\u062a\u0628\u0649 \u062d\u062a\u0649 \u062a\u0631\u0636\u0649 \u0648\u0644\u0627 \u062d\u0648\u0644 \u0648\u0644\u0627 \u0642\u0648\u0629 \u0625\u0644\u0627 \u0628\u0643.","- \u0627\u0644\u0644\u0647\u064f\u0645\u0651\u064e\u0651\u064e \u0625\u0646\u0651\u0627 \u0646\u0639\u0648\u0630 \u0628\u0643 \u0645\u0646 \u062c\u0647\u062f \u0627\u0644\u0628\u0644\u0627\u0621 \u0648\u062f\u0631\u0643 \u0627\u0644\u0634\u0642\u0627\u0621 \u0648\u0633\u0648\u0621 \u0627\u0644\u0642\u0636\u0627\u0621 \u0648\u0634\u0645\u0627\u062a\u0629 \u0627\u0644\u0623\u0639\u062f\u0627\u0621."],t.s)
B.asM=new A.dg("3","\u0623\u062f\u0639\u064a\u0629 \u0632\u0648\u0627\u0644 \u0627\u0644\u0647\u064e\u0640\u0645\u0651\u0650 \u0648\u0627\u0644\u062d\u0640\u0640\u0632\u0646",B.aHA)
B.aSY=s(["- \u0627\u0644\u0644\u0647\u064f\u0640\u0645 \u0639\u0627\u0641\u0650\u0640\u0646\u064a \u0641\u064a \u0628\u064e\u062f\u064e\u0646\u0640\u064a\u060c \u0627\u0644\u0644\u0647\u064f\u0640\u0645 \u0639\u0627\u0641\u0650\u0640\u0646\u064a \u0641\u064a \u0633\u064e\u0645\u0640\u0639\u064a\u060c \u0627\u0644\u0644\u0647\u064f\u0640\u0645 \u0639\u0627\u0641\u0650\u0640\u0646\u064a \u0641\u064a \u0628\u064e\u0635\u064e\u0640\u0631\u064a\u060c \u0644\u0627 \u0625\u0644\u0647\u064e \u0625\u0644\u0627 \u0623\u0646\u0640\u062a.","- \u0627\u0644\u0644\u0647\u0645 \u0625\u0646\u064a \u0623\u0639\u0648\u0630 \u0628\u0643 \u0645\u0646 \u0627\u0644\u0643\u0641\u0631 \u0648\u0627\u0644\u0641\u0642\u0631\u060c \u0627\u0644\u0644\u0647\u0645 \u0625\u0646\u064a \u0623\u0639\u0648\u0630 \u0628\u0643 \u0645\u0646 \u0639\u0630\u0627\u0628 \u0627\u0644\u0642\u0628\u0631\u060c \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0623\u0646\u062a.","\u062b\u0644\u0627\u062b\u0627 \u062d\u064a\u0646 \u062a\u0635\u0628\u062d \u0648\u062b\u0644\u0627\u062b\u0627 \u062d\u064a\u0646 \u062a\u0645\u0633\u064a \u060c \u0643\u0645\u0627 \u0648\u0631\u062f \u0641\u0649 \u0635\u062d\u064a\u062d \u0623\u0628\u064a \u062f\u0627\u0648\u062f \u0628\u0625\u0633\u0646\u0627\u062f\u0647 \u062d\u0633\u0646.","","\u0627\u0644\u0644\u0647\u064f\u0640\u0645 \u0625\u0650\u0646\u0650\u0640\u064a \u0623\u0633\u0640\u0623\u0644\u0640\u0643\u064e \u0627\u0644\u0639\u0640\u0641\u0648\u064e \u0648\u0627\u0644\u0639\u0640\u0627\u0641\u0650\u0640\u064a\u0629 \u0641\u064a \u0627\u0644\u062f\u0646\u0640\u064a\u0627 \u0648\u064e\u0627\u0644\u0622\u062e\u0650\u0640\u0631\u064e\u0629\u060c \u0627\u0644\u0644\u0647\u064f\u0640\u0645 \u0625\u0650\u0646\u0650\u0651\u0640\u064a \u0623\u0633\u0640\u0623\u0644\u0640\u0643 \u0627\u0644\u0639\u0640\u0641\u0648\u064e \u0648\u064e\u0627\u0644\u0639\u0640\u0627\u0641\u0650\u0640\u064a\u0629 \u0641\u064a \u062f\u064a\u0646\u064a \u0648\u062f\u0646\u0640\u064a\u0627\u064a\u064e \u0648\u0623\u0647\u0640\u0644\u064a \u0648\u0645\u0627\u0644\u0640\u064a\u060c \u0627\u0644\u0644\u0647\u064f\u0640\u0645 \u0627\u0633\u062a\u064f\u0640\u0631 \u0639\u0640\u0648\u0631\u0627\u062a\u064a \u0648\u0622\u0645\u0650\u0640\u0646 \u0631\u064e\u0648\u0639\u0627\u062a\u0640\u064a\u060c \u0627\u0644\u0644\u0647\u064f\u0640\u0645 \u0627\u062d\u0641\u0638\u0640\u0646\u064a \u0645\u0646 \u0628\u0640\u064a\u0646\u0650 \u064a\u062f\u064a \u0648\u0645\u0650\u0646 \u062e\u0644\u0641\u0640\u064a \u0648\u0639\u0646 \u064a\u0645\u0640\u064a\u0646\u064a \u0648\u0639\u0646 \u0634\u0650\u0645\u0640\u0627\u0644\u064a \u0648\u0645\u0646 \u0641\u0648\u0642\u0640\u064a\u060c \u0648\u0623\u0639\u0640\u0648\u0630 \u0628\u0650\u0639\u064e\u0638\u0645\u0640\u062a\u0650\u0643 \u0623\u0646 \u0623\u064f\u063a\u0640\u062a\u0627\u0644\u064e \u0645\u0646 \u062a\u062d\u062a\u0640\u064a."],t.s)
B.asR=new A.dg("4","\u062f\u0639\u0627\u0621 \u0627\u0644\u0639\u0627\u0641\u064a\u0629 \u0648\u062d\u0641\u0638 \u0627\u0644\u0628\u062f\u0646",B.aSY)
B.aRh=s(["\u0639\u0646 \u062c\u0627\u0628\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0642\u0627\u0644 : \u0643\u0627\u0646 \u0631\u0633\u064f\u0648\u0644 \u0627\u0644\u0644\u064e\u0651\u0647\u0650 \ufdfa \u064a\u0639\u0644\u0645\u064f\u0646\u0627 \u0627\u0644\u0627\u0633\u062a\u0650\u062e\u0627\u0631\u0629\u064e \u0641\u0650\u064a \u0627\u0644\u0623\u0645\u0648\u0631 \u0643\u0644\u0650\u0647\u064e\u0627 \u0643\u0645\u0627 \u064a\u064f\u0639\u0644\u0650\u0645\u0646\u0627 \u0627\u0644\u0633\u0648\u0631\u064e\u0629\u064e \u0645\u0650\u0646 \u0627\u0644\u0642\u0631\u0622\u0646\u0650 \u064a\u064e\u0642\u0648\u0644: \u0625\u0630\u0627 \u0647\u0645 \u0623\u062d\u062f\u064f\u0643\u0645 \u0628\u0627\u0644\u0623\u0645\u0631 \u0641\u0644\u064a\u0631\u0643\u0639 \u0631\u0643\u0639\u062a\u064a\u0652\u0646\u0650 \u0645\u0650\u0646 \u063a\u064a\u0631\u0650 \u0627\u0644\u0641\u064e\u0631\u0650\u064a\u0636\u0629\u0650 \u062b\u0645 \u0644\u064a\u0642\u0644: \u0627\u0644\u0644\u0647\u064f\u0645\u064e \u0625\u0646\u0650\u064a \u0623\u0633\u062a\u062e\u0650\u064a\u0631\u064f\u0643\u064e \u0628\u0639\u0644\u0645\u0643\u064e\u060c \u0648\u0623\u0633\u062a\u0642\u062f\u0650\u0631\u0643 \u0628\u0650\u0642\u062f\u0631\u062a\u0650\u0643\u060c \u0648\u0623\u0633\u0623\u0644\u0643 \u0645\u0646 \u0641\u0636\u0644\u0650\u0643\u064e \u0627\u0644\u0639\u064e\u0638\u0650\u064a\u0645\u0650 \u0641\u0625\u0650\u0646\u0643\u064e \u062a\u0642\u062f\u0650\u0631\u064f \u0648\u0644\u0627 \u0623\u0642\u062f\u0650\u0631\u064f\u060c \u0648\u062a\u0639\u0644\u064e\u0645\u064f \u0648\u0644\u0627 \u0623\u0639\u0644\u064e\u0645\u060c \u0648\u0623\u0646\u062a\u064e \u0639\u064e\u0644\u0627\u0645 \u0627\u0644\u063a\u064a\u064f\u0648\u0628\u0650\u060c \u0627\u0644\u0644\u0647\u064f\u0645\u064e \u0625\u0646 \u0643\u064f\u0646\u062a \u062a\u0639\u0644\u0645 \u0623\u0646 \u0647\u0630\u0627 \u0627\u0644\u0623\u064e\u0645\u0652\u0631\u064e - ........... - \u062e\u064a\u0631 \u0644\u064a \u0641\u064a \u062f\u064a\u0646\u064a \u0648\u0645\u0639\u064e\u0627\u0634\u064a \u0648\u0639\u0627\u0642\u0650\u0628\u0629\u0650 \u0623\u0645\u0631\u064a\u060c \u0641\u0627\u0642\u062f\u064f\u0631\u0647 \u0644\u064a \u0648\u064a\u0633\u0631\u0647\u064f \u0644\u0650\u064a \u062b\u0645\u064e \u0628\u0627\u0631\u0650\u0643 \u0644\u064a \u0641\u064a\u0647\u0650\u060c \u0627\u0644\u0644\u0647\u064f\u0645\u064e \u0648\u0625\u0650\u0646 \u0643\u0646\u062a \u062a\u0639\u0644\u0645\u064f \u0623\u0646 \u0647\u0630\u0627 \u0627\u0644\u0623\u0645\u0631 - .......... - \u0634\u0631 \u0644\u064a \u0641\u064a \u062f\u064a\u0646\u064a \u0648\u0645\u0639\u0627\u0634\u0650\u064a \u0648\u0639\u0627\u0642\u0628\u0629\u0650 \u0623\u0645\u0631\u0650\u064a\u060c \u0641\u0627\u0635\u0631\u0641\u0647\u064f \u0639\u0646\u0650\u064a \u0648\u0627\u0635\u0631\u0650\u0641\u0646\u0650\u064a \u0639\u0646\u0647\u064f \u0648\u0627\u0642\u062f\u064f\u0631 \u0644\u064a \u0627\u0644\u062e\u064a\u0631\u064e \u062d\u064a\u062b \u0643\u0627\u0646\u064e \u062b\u0645 \u0627\u0631\u0636\u0646\u0650\u064a \u0628\u0650\u0647\u0650 - \u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a.","\u0643\u064a\u0641\u064a\u0651\u0629 \u0627\u0644\u0635\u0644\u0627\u0629:","- \u0627\u0644\u0648\u0636\u0648\u0621 \u0648\u0646\u064a\u0651\u0629 \u0627\u0644\u0642\u0644\u0628 \u0648\u062a\u0643\u0648\u0646 \u0631\u0643\u0639\u062a\u064a\u0646 \u062f\u0648\u0646 \u0627\u0644\u0641\u0631\u064a\u0636\u0629.","- \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0641\u0627\u062a\u062d\u0629 \u0648\u0633\u0648\u0631\u0629 \u0642\u0635\u064a\u0631\u0629 \u0648\u0645\u0646 \u0627\u0644\u0633\u0651\u0646\u0629 \u0642\u0631\u0627\u0621\u0629 \u0633\u0648\u0631\u0629 \u0627\u0644\u0643\u0627\u0641\u0631\u0648\u0646 \u0641\u0649 \u0627\u0644\u0631\u0651\u0643\u0639\u0629 \u0627\u0644\u0623\u0648\u0644\u0649 \u0648\u0633\u0648\u0631\u0629 \u0627\u0644\u0625\u062e\u0644\u0627\u0635 \u0641\u0649 \u0627\u0644\u0631\u0651\u0643\u0639\u0629 \u0627\u0644\u062b\u0651\u0627\u0646\u064a\u0629.","- \u0648\u064a\u0642\u0627\u0644 \u062f\u0639\u0627\u0621 \u0627\u0644\u0623\u0633\u062a\u062e\u0627\u0631\u0629 \u0628\u0639\u062f \u0627\u0644\u062a\u0634\u0647\u062f\u060c \u0642\u0628\u0644 \u0627\u0644\u062a\u0651\u0633\u0644\u064a\u0645.","\u0648\u064a\u0646\u0628\u063a\u064a \u0644\u0644\u0645\u0624\u0645\u0646 \u0623\u0644\u0627 \u064a\u0642\u0635\u062f \u0634\u064a\u0626\u0627 \u0645\u0646 \u062f\u0642\u064a\u0642 \u0627\u0644\u0623\u0645\u0648\u0631 \u062d\u062a\u0649 \u064a\u0633\u062a\u062e\u064a\u0631 \u0627\u0644\u0644\u0647 \u0641\u064a\u0647\u060c \u0648\u064a\u0633\u0623\u0644\u0647 \u0623\u0646 \u064a\u062d\u0645\u0644\u0647 \u0641\u064a\u0647 \u0639\u0644\u0649 \u0627\u0644\u062e\u064a\u0631 \u0648\u064a\u0635\u0631\u0641 \u0639\u0646\u0647 \u0627\u0644\u0634\u0631\u060c \u0648\u0623\u0646 \u064a\u0643\u0648\u0646 \u0627\u0644\u0645\u0624\u0645\u0646 \u0639\u0644\u0649 \u064a\u0642\u064a\u0646 \u0628\u0623\u0646 \u0644\u0627 \u064a\u0639\u0644\u0645 \u0627\u0644\u063a\u064a\u0628 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647\u060c \u0648\u0644\u0627 \u064a\u064f\u0642\u062f\u0631 \u0627\u0644\u062e\u064a\u0631 \u0623\u0648 \u0627\u0644\u0634\u0631 \u0644\u0644\u0639\u0628\u062f \u0633\u0648\u0649 \u0627\u0644\u0644\u0647 \u0639\u0632 \u0648\u062c\u0644."],t.s)
